BIBLIOTECA_GET_ROUTES.forEach(route => app.get(route, (req, res) => relayGetFromBiblioteca(req, res)));

async function relayPutToBiblioteca(req: Request, res: Response) {
  const upstreamPath = req.originalUrl;
  const upstreamUrl = `${BIBLIOTECA_SERVER_URL}${upstreamPath}`;
  try {
    const upstreamRes = await fetch(upstreamUrl, {
      method: 'PUT',
      headers: { ...forwardedHeaders(req), 'Content-Type': 'application/json' },
      body: JSON.stringify(req.body ?? {}),
      redirect: 'manual'
    });
    relaySetCookie(upstreamRes, res);
    const contentType = upstreamRes.headers.get('content-type') || 'application/octet-stream';
    res.status(upstreamRes.status);
    res.setHeader('Content-Type', contentType);
    res.send(Buffer.from(await upstreamRes.arrayBuffer()));
  } catch (error: any) {
    res.status(502).json({ error: `biblioteca-server unreachable at ${BIBLIOTECA_SERVER_URL}: ${error.message}` });
  }
}

// Every other PUT this app actually needs - preferencesStore.ts's
// RemotePreferencesStore calls this one. (The /api/reading-progress* PUTs
