// Write traffic, so read-only deployments 403 them.
['/api/users/me/preferences']
  .forEach(route => app.put(route, unlessReadOnly(relayPutToBiblioteca)));

// Saved searches and collection edits (biblioteca-server's /api/collections/mine
// family) - explicit routes like every other one here, never a wildcard.
function relayBodyToBiblioteca(method: 'POST' | 'PATCH' | 'DELETE') {
  return async (req: Request, res: Response) => {
    try {
      const upstreamRes = await fetch(`${BIBLIOTECA_SERVER_URL}${req.originalUrl}`, {
        method,
        headers: { ...forwardedHeaders(req), 'Content-Type': 'application/json' },
        body: method === 'DELETE' ? undefined : JSON.stringify(req.body ?? {}),
        redirect: 'manual'
      });
      relaySetCookie(upstreamRes, res);
      res.status(upstreamRes.status);
      res.setHeader('Content-Type', upstreamRes.headers.get('content-type') || 'application/octet-stream');
      res.send(Buffer.from(await upstreamRes.arrayBuffer()));
    } catch (error: any) {
      res.status(502).json({ error: `biblioteca-server unreachable at ${BIBLIOTECA_SERVER_URL}: ${error.message}` });
    }
  };
}
app.post('/api/collections/mine/searches', unlessReadOnly(relayBodyToBiblioteca('POST')));
app.patch('/api/collections/mine/:id', unlessReadOnly(relayBodyToBiblioteca('PATCH')));
app.delete('/api/collections/mine/:id', unlessReadOnly(relayBodyToBiblioteca('DELETE')));
app.put('/api/collections/mine/:id/order', unlessReadOnly(relayPutToBiblioteca));
// The server's own /graphql, same-origin: read access to the signed-in
// reader's collections (myCollections) goes through here. Queries only, so
// it stays reachable in read-only mode.
app.post('/graphql', relayBodyToBiblioteca('POST'));

// Same-origin proxy for biblioteca-nestjs's own unauthenticated status
// endpoint - the admin page's indexing-progress card (IndexingProgressCard)
// polls this. No cookie relay needed, unlike the biblioteca-server routes
// above - nestjs has no auth on it at all, which is exactly why this
// can't be a wildcard: anything else under nestjs (including its
// manual-only /api/vector-store/reset and /api/vector-store/remove-opus)
// must never be reachable through here.
app.get('/api/vectorizing', asyncRoute(async (req: Request, res: Response) => {
  const upstreamUrl = `${NESTJS_URL}/api/vectorizing`;
  try {
    const upstreamRes = await fetch(upstreamUrl, { headers: { Accept: 'application/json' } });
    const contentType = upstreamRes.headers.get('content-type') || 'application/json';
    const bodyBuffer = Buffer.from(await upstreamRes.arrayBuffer());
    res.status(upstreamRes.status);
    res.setHeader('Content-Type', contentType);
    res.send(bodyBuffer);
  } catch (error: any) {
    res.status(502).json({ error: `biblioteca-nestjs unreachable at ${NESTJS_URL}: ${error.message}` });
  }
}));

// Same-origin gateway to biblioteca-server's public build identity (the
// unauthenticated /api/info endpoint, no admin gate by design) plus the
// process uptime metric from Actuator - exposed on the compose network
// (management.endpoints.web.exposure.include includes metrics); only
// Caddy keeps /actuator/** away from the internet, not the reader's
// relay. The admin sidebar's footer and status cards show the
// actually-deployed server version/uptime instead of stale mocks.
app.get('/api/server-info', asyncRoute(async (req: Request, res: Response) => {
  try {
    const [infoRes, uptimeRes] = await Promise.allSettled([
      fetch(`${BIBLIOTECA_SERVER_URL}/api/info`, { headers: { Accept: 'application/json' } }),
      fetch(`${BIBLIOTECA_SERVER_URL}/actuator/metrics/process.uptime`, { headers: { Accept: 'application/json' } }),
    ]);
    if (infoRes.status !== 'fulfilled' || !infoRes.value.ok) {
      res.status(502).json({ error: `biblioteca-server unreachable at ${BIBLIOTECA_SERVER_URL}` });
      return;
    }
    const info = await infoRes.value.json() as Record<string, unknown>;
    if (uptimeRes.status === 'fulfilled' && uptimeRes.value.ok) {
      const metric = await uptimeRes.value.json() as { measurements?: { statistic?: string; value?: number }[] };
      const seconds = metric.measurements?.find(m => m.statistic === 'VALUE')?.value;
      if (typeof seconds === 'number') info.uptimeSeconds = seconds;
    }
    res.setHeader('Content-Type', 'application/json');
    res.send(info);
  } catch (error: any) {
    res.status(502).json({ error: `biblioteca-server unreachable at ${BIBLIOTECA_SERVER_URL}: ${error.message}` });
  }
}));

// Render a cover for the work currently open in the reader. This is a narrow
// same-origin gateway rather than a generic proxy: callers provide stable
// work metadata, while the theme is selected here and arbitrary upstream
// paths cannot be reached through the reader.
app.post('/api/covers/work', asyncRoute(async (req: Request, res: Response) => {
  const { workId, title, author, subtitle, date, coverArtUrl } = req.body ?? {};
  if (typeof title !== 'string' || !title.trim() || typeof author !== 'string' || !author.trim()) {
    res.status(400).json({ error: 'title and author are required' });
    return;
  }
  if (workId !== undefined && (typeof workId !== 'string' || !/^[^/]+\/[^/]+$/.test(workId.trim()))) {
    res.status(400).json({ error: 'workId must be a canonical authorId/opusId path' });
    return;
  }
  if (coverArtUrl !== undefined && typeof coverArtUrl !== 'string') {
    res.status(400).json({ error: 'coverArtUrl must be a URL string' });
    return;
  }

  if (workId) {
    const cached = await readCachedCover(workId);
    if (cached) {
      res.setHeader('Content-Type', 'image/png');
      res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
      res.setHeader('X-Biblioteca-Cover-Cache', 'HIT');
      res.send(cached);
      return;
    }
  }

  const layout = COVER_LAYOUTS[Math.floor(Math.random() * COVER_LAYOUTS.length)];
  const paletteId = COVER_PALETTES[Math.floor(Math.random() * COVER_PALETTES.length)];
  const coverRequest = {
    title: title.trim(),
    author: author.trim(),
    ...(typeof subtitle === 'string' && subtitle.trim() ? { subtitle: subtitle.trim() } : {}),
    ...(typeof date === 'string' && date.trim() ? { date: date.trim() } : {}),
    ...(typeof coverArtUrl === 'string' && coverArtUrl.trim() ? { coverArtUrl: coverArtUrl.trim() } : {}),
    layout,
    foilEffect: 'none',
    hardcover: false,
    format: 'png',
    pixelRatio: 2,
    theme: { paletteId, showBarcode: false },
  };

  try {
    const upstreamRes = await fetch(`${COVERS_API_URL}/api/cover`, {
      method: 'POST',
      headers: {
        Accept: 'image/png',
        'Content-Type': 'application/json',
        ...(workId ? { 'X-Biblioteca-Work-Id': workId } : {}),
      },
      body: JSON.stringify(coverRequest),
      signal: AbortSignal.timeout(60_000),
    });
    const body = Buffer.from(await upstreamRes.arrayBuffer());
    res.status(upstreamRes.status);
    res.setHeader('Content-Type', upstreamRes.headers.get('content-type') || 'application/octet-stream');
    if (!upstreamRes.ok) {
      res.json({ error: `Cover renderer returned HTTP ${upstreamRes.status}` });
      return;
    }
    if (workId && coverCache) {
      try {
        await writeCachedCover(workId, body);
      } catch (error: any) {
        console.warn(`Cover cache write failed for ${workId}: ${error?.message || error}`);
      }
    }
    if (workId) res.setHeader('X-Biblioteca-Work-Id', workId);
    res.setHeader('Cache-Control', coverCache ? 'public, max-age=31536000, immutable' : 'no-store');
    if (coverCache) res.setHeader('X-Biblioteca-Cover-Cache', 'MISS');
    res.send(body);
  } catch (error: any) {
    const message = error?.name === 'TimeoutError'
      ? 'Cover renderer timed out after 60 seconds'
      : `Cover renderer unreachable at ${COVERS_API_URL}: ${error?.message || 'unknown error'}`;
    res.status(502).json({ error: message });
  }
}));

// A stable, GET-able og:image URL for a work - unlike the POST route
// above (which the client calls with the work's title/author already in
// hand), social crawlers can only ever follow a plain <meta
// property="og:image"> URL, so this looks the work up itself. Reuses the
// same MinIO cache/cache-key as the POST route (readCachedCover/
// writeCachedCover), so a page view through either path warms the same
// cached object and a cache hit here never touches the covers renderer.
app.get('/api/covers/work/:authorId/:opusId', asyncRoute(async (req: Request, res: Response) => {
  const workId = `${req.params.authorId}/${req.params.opusId}`;

  const cached = await readCachedCover(workId);
  if (cached) {
    res.setHeader('Content-Type', 'image/png');
    res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
    res.setHeader('X-Biblioteca-Cover-Cache', 'HIT');
    res.send(cached);
    return;
  }

  let title: string | undefined;
  let author: string | undefined;
  try {
    const divRes = await fetch(`${BIBLIOTECA_SERVER_URL}/api/divs?path=${encodeURIComponent(workId)}`, {
      headers: { Accept: 'application/json' }
    });
    if (!divRes.ok) {
      res.status(404).end();
      return;
    }
    const div = await divRes.json() as { id?: number; head?: string; author?: { displayName?: string; visualName?: string; firstName?: string; lastName?: string } };
    if (!div.id) {
      res.status(404).end();
      return;
    }
    title = div.head || workId;
    const authorDiv = div.author;
    author = authorDiv?.displayName || authorDiv?.visualName
      || [authorDiv?.firstName, authorDiv?.lastName].filter(Boolean).join(' ') || 'Anonymous';
  } catch (error: any) {
    res.status(502).json({ error: `biblioteca-server unreachable at ${BIBLIOTECA_SERVER_URL}: ${error.message}` });
    return;
  }

  const layout = COVER_LAYOUTS[Math.floor(Math.random() * COVER_LAYOUTS.length)];
  const paletteId = COVER_PALETTES[Math.floor(Math.random() * COVER_PALETTES.length)];
  const coverRequest = {
    title, author, layout, foilEffect: 'none', hardcover: false, format: 'png', pixelRatio: 2,
    theme: { paletteId, showBarcode: false },
  };

  try {
    const upstreamRes = await fetch(`${COVERS_API_URL}/api/cover`, {
      method: 'POST',
      headers: { Accept: 'image/png', 'Content-Type': 'application/json', 'X-Biblioteca-Work-Id': workId },
      body: JSON.stringify(coverRequest),
      signal: AbortSignal.timeout(60_000),
    });
    if (!upstreamRes.ok) {
      res.status(502).end();
      return;
    }
    const body = Buffer.from(await upstreamRes.arrayBuffer());
    if (coverCache) {
      try {
        await writeCachedCover(workId, body);
      } catch (error: any) {
        console.warn(`Cover cache write failed for ${workId}: ${error?.message || error}`);
      }
    }
    res.setHeader('Content-Type', 'image/png');
    res.setHeader('Cache-Control', coverCache ? 'public, max-age=31536000, immutable' : 'no-store');
    if (coverCache) res.setHeader('X-Biblioteca-Cover-Cache', 'MISS');
    res.send(body);
  } catch {
    res.status(502).end();
  }
}));

// Admin-only: one work's cover on demand (the work card's back-face admin
// section). The UI only shows the section to administrators, but the gate
// that matters is here: biblioteca-server is asked, with the caller's own
// session cookie, whether this session is an administrator (ADMIN_USERS)
// before anything reaches biblioteca-nestjs, which has no auth of its own.
async function isAdminSession(req: Request): Promise<boolean> {
  try {
    const whoRes = await fetch(`${BIBLIOTECA_SERVER_URL}/api/users/me`, { headers: forwardedHeaders(req) });
    if (!whoRes.ok) return false;
    const who = await whoRes.json() as { authenticated?: boolean; isAdmin?: boolean };
    return Boolean(who.authenticated && who.isAdmin);
  } catch {
    return false;
  }
}

const WORK_PATH = /^[^/]+\/[^/]+$/;

// Typed against biblioteca-nestjs's own OpenAPI (rake gen-vectorizer-client).
const nestjsApi = createClient<NestjsPaths>({
  baseUrl: NESTJS_URL,
  fetch: (...args: Parameters<typeof globalThis.fetch>) => globalThis.fetch(...args),
});

// Synchronous: waits for nestjs to render, store and assign the new cover
// (seconds to a minute), then answers { coverUrl, request }. An optional
// `request` object in the body is the admin-edited cover JSON to render
// from; without it nestjs picks a random request as before.
// Renders, stores and assigns a cover upstream - write traffic, 403 in
// read-only deployments.
app.post('/api/admin/covers/work', unlessReadOnly(asyncRoute(async (req: Request, res: Response) => {
  const path = req.body?.path;
  if (typeof path !== 'string' || !WORK_PATH.test(path)) {
    res.status(400).json({ error: 'path must be authorStrId/opusStrId' });
    return;
  }
  const request = req.body?.request;
  if (request !== undefined && (request === null || typeof request !== 'object' || Array.isArray(request))) {
    res.status(400).json({ error: 'request must be a JSON object' });
    return;
  }
  if (!(await isAdminSession(req))) {
    res.status(403).json({ error: 'administrators only' });
    return;
  }
  try {
    const { data, error, response } = await nestjsApi.POST('/api/covers/work', {
      body: { path, ...(request ? { request } : {}) },
      signal: AbortSignal.timeout(180_000),
    });
    res.status(response.status).json(data ?? error ?? {});
  } catch (error: any) {
    res.status(502).json({ error: `biblioteca-nestjs unreachable at ${NESTJS_URL}: ${error.message}` });
  }
})));

// A fresh random cover request JSON for the work, without rendering it -
// the admin section's "New random JSON" button fills its editor from this.
app.get('/api/admin/covers/work/request/random', asyncRoute(async (req: Request, res: Response) => {
  const path = typeof req.query.path === 'string' ? req.query.path : '';
  if (!WORK_PATH.test(path)) {
    res.status(400).json({ error: 'path must be authorStrId/opusStrId' });
    return;
  }
  if (!(await isAdminSession(req))) {
    res.status(403).json({ error: 'administrators only' });
    return;
  }
  try {
    const { data, error, response } = await nestjsApi.GET('/api/covers/work/request/random', { params: { query: { path } } });
    res.status(response.status).json(data ?? error ?? {});
  } catch (error: any) {
    res.status(502).json({ error: `biblioteca-nestjs unreachable at ${NESTJS_URL}: ${error.message}` });
  }
}));

// The request JSON the work's current cover was rendered from (null for
// covers rendered before requests were recorded).
app.get('/api/admin/covers/work/request', asyncRoute(async (req: Request, res: Response) => {
  const path = typeof req.query.path === 'string' ? req.query.path : '';
  if (!WORK_PATH.test(path)) {
    res.status(400).json({ error: 'path must be authorStrId/opusStrId' });
    return;
  }
  if (!(await isAdminSession(req))) {
    res.status(403).json({ error: 'administrators only' });
    return;
  }
  try {
    const { data, error, response } = await nestjsApi.GET('/api/covers/work/request', { params: { query: { path } } });
    res.status(response.status).json(data ?? error ?? {});
  } catch (error: any) {
    res.status(502).json({ error: `biblioteca-nestjs unreachable at ${NESTJS_URL}: ${error.message}` });
  }
}));

// POST passthrough for nestjs's vectorizing controls (start/pause/resume -
// see IndexingProgressCard's stop/resume buttons). Fire-and-forget on
// purpose: start/resume don't resolve until the whole run finishes (can be
// hours - see VectorizingJobService.vectorizeOpera), so awaiting the
// upstream call here would just hang this request too. The admin page's
// existing poll of GET /api/vectorizing picks up the new running/paused
// state within a few seconds regardless of when (or whether) this
// resolves. :action is constrained to the three real controls - anything
// else 404s before ever reaching nestjs.
app.post('/api/vectorizing/:action(start|pause|resume)', unlessReadOnly((req: Request, res: Response) => {
  const upstreamUrl = `${NESTJS_URL}/api/vectorizing/${req.params.action}`;
  fetch(upstreamUrl, { method: 'POST' }).catch((error: any) => {
    console.error(`[vz-proxy] POST ${upstreamUrl} failed: ${error.message}`);
  });
  res.status(202).json({ accepted: true });
}));

// The one deliberately broad route: the reading surface itself (author/
// opus/chapter content, four content-negotiated formats - see
// biblioteca-server's own README, this is the part explicitly meant to be
// public and crawlable) - kept under its own /api/server-content/* prefix since it isn't
// part of the /api/** contract above. Anything reaching here shaped like
// an API or actuator call was never one of the routes this app actually
// uses (all of which are registered above, under /api/** directly, and
// so already won the match before Express ever gets here), so it's
// refused rather than silently forwarded.
// The pages relayed through /api/server-content are biblioteca-server's own
// full pages, and their asset links are root-absolute on the server's
// origin (/css/teidiv.css, /bootstrap-5.2.1-dist/..., /img/...). On this
// origin they would fall through to the SPA fallback and 404 as assets,
// leaving the relayed page unstyled. Relay the server's static asset
// prefixes too, so a relayed page renders exactly as it does on
// biblioteca-server itself - per URL, since each page carries its own
// asset list. No collisions: this app's own surface is /api/*, /app,
// /robots.txt, /sitemap.xml (the dist build's assets live under /assets).
['/css', '/img', '/js', '/bootstrap-5.2.1-dist']
  .forEach(prefix => app.get(`${prefix}/*`, (req: Request, res: Response) =>
    void relayGetFromBiblioteca(req, res, req.originalUrl)));

app.get('/api/server-content/*', asyncRoute(async (req: Request, res: Response) => {
  const upstreamPath = req.originalUrl.replace(/^\/api\/server-content/, '');
  if (upstreamPath.startsWith('/api/') || upstreamPath.startsWith('/actuator')) {
    res.status(404).json({ error: 'not a public endpoint' });
    return;
  }
  await relayGetFromBiblioteca(req, res, upstreamPath);
}));

// This app's own public API contract - see openapi-public.ts. Internal
// (unauthenticated) by convenience, not by design: nothing here should
// ever describe biblioteca-server's or biblioteca-nestjs's real surface,
// only this file's own explicit proxy routes and payment endpoints.
// Matches biblioteca-server's own convention exactly (/api/docs the raw
// spec, /api/ui the interactive page) for consistency across the family.
app.get('/api/docs', (req: Request, res: Response) => res.json(openApiPublicDoc));
app.use('/api/ui', swaggerUi.serve, swaggerUi.setup(openApiPublicDoc));

// Google One Tap credential exchange. textbase-server's own POST
// /api/auth/google expects a real HTML form POST (form-encoded `credential`,
// responds with a redirect - see GoogleAuthController) since it's designed
// for Google's widget to submit directly. Our own widget instead delivers
// the credential to a JS callback (see components/GoogleOneTap.tsx, same
// pattern as roundsq-ui's), so this endpoint bridges the two: takes a JSON
// {credential}, POSTs it upstream as textbase-server expects, and turns
// its redirect-shaped response into a plain JSON success/failure the
// widget's fetch call can actually use - while still relaying the real
// session cookie back to the browser on success.
// Sign-in mints a session upstream (a write), so read-only deployments 403
// the whole auth family - the reader degrades to anonymous public browsing.
app.post('/api/auth/google', unlessReadOnly(asyncRoute(async (req: Request, res: Response) => {
  const credential = req.body?.credential;
  console.debug(`[tb-proxy][google-auth] request received, credential present=${Boolean(credential)}, length=${credential?.length ?? 0}, incoming cookie present=${Boolean(req.headers.cookie)}`);
  if (!credential) {
    console.debug('[tb-proxy][google-auth] rejecting: no credential in request body');
    res.status(400).json({ success: false, error: 'missing credential' });
    return;
  }
  try {
    console.debug(`[tb-proxy][google-auth] forwarding to ${BIBLIOTECA_SERVER_URL}/api/auth/google`);
    const upstreamRes = await fetch(`${BIBLIOTECA_SERVER_URL}/api/auth/google`, {
      method: 'POST',
      headers: { ...forwardedHeaders(req, 'text/html'), 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ credential }).toString(),
      redirect: 'manual'
    });
    const cookiesOut = upstreamRes.headers.getSetCookie?.() ?? [];
    console.debug(`[tb-proxy][google-auth] upstream responded status=${upstreamRes.status}, location=${upstreamRes.headers.get('location')}, set-cookie count=${cookiesOut.length}`);
    relaySetCookie(upstreamRes, res);
    const location = upstreamRes.headers.get('location') || '';
    const errorMatch = location.match(/[?&]googleSignInError=([^&]*)/);
    if (errorMatch) {
      console.debug(`[tb-proxy][google-auth] upstream reported a sign-in error: ${decodeURIComponent(errorMatch[1])}`);
      res.status(401).json({ success: false, error: decodeURIComponent(errorMatch[1]) });
      return;
    }
    if (upstreamRes.status >= 300 && upstreamRes.status < 400) {
      console.debug('[tb-proxy][google-auth] success - session cookie relayed to browser');
      res.json({ success: true });
      return;
    }
    console.debug(`[tb-proxy][google-auth] unexpected upstream status ${upstreamRes.status}, treating as failure`);
    res.status(502).json({ success: false, error: `unexpected textbase-server response (${upstreamRes.status})` });
  } catch (error: any) {
    console.debug(`[tb-proxy][google-auth] FAILED to reach textbase-server: ${error.message}`);
    res.status(502).json({ success: false, error: `biblioteca-server unreachable at ${BIBLIOTECA_SERVER_URL}: ${error.message}` });
  }
})));

// Refresh the signed-in user's Google profile photo. The access token never
// leaves this same-origin proxy and is sent only to biblioteca-server, which
// validates it against the current session before persisting the photo URL.
app.post('/api/auth/google/profile', unlessReadOnly(asyncRoute(async (req: Request, res: Response) => {
  const accessToken = req.body?.access_token;
  if (!accessToken) {
    res.status(400).json({ success: false, error: 'missing access token' });
    return;
  }
  try {
    const upstreamRes = await fetch(`${BIBLIOTECA_SERVER_URL}/api/auth/google/profile`, {
      method: 'POST',
      headers: { ...forwardedHeaders(req, 'application/json'), 'Content-Type': 'application/json' },
      body: JSON.stringify({ access_token: accessToken }),
    });
    relaySetCookie(upstreamRes, res);
    const body = await upstreamRes.text();
    res.status(upstreamRes.status).type('application/json').send(body);
  } catch (error: any) {
    res.status(502).json({ success: false, error: `biblioteca-server unreachable at ${BIBLIOTECA_SERVER_URL}: ${error.message}` });
  }
})));

// Real sign-out. textbase-server has no custom logout endpoint - this is
// Spring Security's own default POST /logout (invalidates the session,
// clears the security context; CSRF is disabled app-wide, so no token is
// needed - see SecurityConfig). Bridged the same way as /api/auth/google
// above: relay the browser's cookie up, relay whatever Set-Cookie (the
// now-invalidated session) comes back, and report plain JSON success
// rather than following textbase-server's own redirect.
app.post('/api/auth/logout', unlessReadOnly(asyncRoute(async (req: Request, res: Response) => {
  console.debug('[tb-proxy][google-auth] sign-out requested, incoming cookie present=', Boolean(req.headers.cookie));
  try {
    const upstreamRes = await fetch(`${BIBLIOTECA_SERVER_URL}/logout`, {
      method: 'POST',
      headers: forwardedHeaders(req, 'text/html'),
      redirect: 'manual'
    });
    console.debug(`[tb-proxy][google-auth] sign-out upstream status=${upstreamRes.status}`);
    relaySetCookie(upstreamRes, res);
    res.json({ success: true });
  } catch (error: any) {
    console.debug(`[tb-proxy][google-auth] sign-out FAILED to reach textbase-server: ${error.message}`);
    res.status(502).json({ success: false, error: `biblioteca-server unreachable at ${BIBLIOTECA_SERVER_URL}: ${error.message}` });
  }
})));

// 4. Check user book unlock & purchase status
app.get('/api/payment/purchases/:userId', (req: Request, res: Response) => {
  const { userId } = req.params;
  const userPurchases = Object.values(verifiedPurchases).filter(p => p.userId === userId);
  res.json({
    userId,
    purchases: userPurchases,
    purchasedWorkIds: userPurchases.map(p => p.workId)
  });
});

// Health check endpoint
app.get('/api/health', (req: Request, res: Response) => {
  res.json({
    status: 'ok',
    service: 'textbase-reader-api',
    readOnly: READ_ONLY,
    stripeConfigured: Boolean(process.env.STRIPE_SECRET_KEY),
    timestamp: new Date().toISOString()
  });
});

// Service info: the precise version of the project being served, in the
// same shape as biblioteca-server's /api/info and biblioteca-nestjs's
// /api/info, so all three services answer the version question the same
// way.
app.get('/api/info', (req: Request, res: Response) => {
  res.json({
    name: packageInfo.name,
    version: packageInfo.version
  });
});

// ==========================================
// VITE CLIENT / SPA MIDDLEWARE
// ==========================================
// The default social-share feature image: what Facebook/Twitter/etc. show
// for any page buildPageSeo() can't resolve real content for (home,
// admin, search, an unresolvable id). Pass-store-driven like
// BIBLIOTECA_EXTERNAL_URL etc. (biblioteca/<profile>'s OG_DEFAULT_IMAGE_URL)
// rather than a file shipped in this repo, since it's shared, non-secret
// config, not something that should need a redeploy to swap. Falls back
// to the bundled public/cover-blue.jpg when unset (local dev without the
// pass store loaded) - a jpeg deliberately, the safe choice for the
// social crawlers' size limits.
const OG_FALLBACK_IMAGE_PATH = 'cover-blue.jpg';

// The public site mounts this app at /app (Caddy's handle_path strips the
// prefix before proxying, so the request path can't recover it); the
// bare-metal dev instance serves the same shell at the root.
function publicBasePath(): string {
  return process.env.NODE_ENV === 'production' ? '/app' : '';
}

function originFor(req: Request): string {
    // Behind Caddy (every public vhost), so trust the forwarded headers;
    // the direct http fallback only ever applies to a localhost check.
    const host = req.get('x-forwarded-host') || req.get('host') || 'biblioteca.scriptorium.ro';
    const proto = req.get('x-forwarded-proto') || req.protocol;
    return `${proto}://${host}`;
}

function defaultOgImage(origin: string): string {
  if (process.env.OG_DEFAULT_IMAGE_URL) {
    return process.env.OG_DEFAULT_IMAGE_URL;
  }
  // In production the site root is biblioteca-server's, which serves the
  // family's og-default.jpg - 1200x630, the size every social platform's
  // large-preview card is built for. The reader's own bundled
  // cover-blue.jpg is 150x230, below Facebook's (200px) and WhatsApp's
  // (300x200) minimums, so crawlers silently drop it - no share image.
  // Bare-metal dev serves only the reader at the root, so it keeps the
  // bundled fallback there.
  return process.env.NODE_ENV === 'production'
    ? `${origin}/img/og-default.jpg`
    : `${origin}/${OG_FALLBACK_IMAGE_PATH}`;
}

app.get('/robots.txt', (req: Request, res: Response) => {
  res.type('text/plain').send(buildRobotsTxt(originFor(req)));
});

// Rebuilt at most once an hour: biblioteca-server's own catalog (~3,800
// works, ~970 authors as of 2026-10) barely changes minute to minute, and
// search engines poll this file unattended - no reason to pay the
// upstream pagination cost on every crawl.
const SITEMAP_TTL_MS = 60 * 60 * 1000;
let sitemapCache: { xml: string; origin: string; builtAt: number } | null = null;

app.get('/sitemap.xml', asyncRoute(async (req: Request, res: Response) => {
  const origin = originFor(req);
  if (!sitemapCache || sitemapCache.origin !== origin || Date.now() - sitemapCache.builtAt > SITEMAP_TTL_MS) {
    const xml = await buildSitemapXml(origin, BIBLIOTECA_SERVER_URL);
    sitemapCache = { xml, origin, builtAt: Date.now() };
  }
  res.type('application/xml').send(sitemapCache.xml);
}));

async function buildReaderPageSeo(options: Parameters<typeof buildPageSeo>[0]) {
  const seo = await buildPageSeo(options);
  return options.route.view === 'quote' ? enrichQuoteSeo(seo, options.route.quoteId, options.bibliotecaServerUrl, options.origin) : seo;
}

async function renderPageFor(req: Request, template: string): Promise<string> {
  const origin = originFor(req);
  const queryIndex = req.url.indexOf('?');
  const search = queryIndex >= 0 ? req.url.slice(queryIndex) : '';
  const route = parseAppPath(req.path, '', search);
  const seo = await buildReaderPageSeo({
    route,
    origin,
    // Caddy strips the /app mount prefix before proxying here, but the
    // shared, public URL still carries it - the canonical/og:url Facebook
    // keys its link-preview cache on must be the public form, or an /app
    // share gets merged into the root URL's cache object (which is how a
    // fresh deploy kept showing the pre-rebrand "TEXT ❖ BASE" preview).
    path: route.view === 'reader' ? canonicalReaderPath(req.path) : req.path,
    searchParams: new URLSearchParams(search),
    bibliotecaServerUrl: BIBLIOTECA_SERVER_URL,
    defaultImage: defaultOgImage(origin),
  });
  const rendered = renderIndexHtml(template, seo);
  return ['reader', 'quote'].includes(route.view) ? rendered.replace('</head>', textAlternates(canonicalReaderPath(req.path), new URLSearchParams(search)) + '</head>') : rendered;
}

async function startServer() {
  registerQuoteTwins(app, { serverUrl: BIBLIOTECA_SERVER_URL, originFor, apiDocument: openApiPublicDoc });
  registerTextTwins(app, { serverUrl: BIBLIOTECA_SERVER_URL, originFor, defaultImage: defaultOgImage });
  app.use('/api', (req: Request, res: Response) => {
    res.status(404).json({ error: 'not found' });
  });

  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
      plugins: [{
        // The bare-metal dev instance's public face is test.scriptorium.ro
        // (Caddy proxies it here), so that is the shareable absolute URL -
        // same buildPageSeo()/renderIndexHtml() as production, just with a
        // fixed origin, so per-page SEO is testable without a prod build.
        name: 'seo-meta',
        transformIndexHtml: {
          order: 'pre',
          handler: async (html: string, ctx: { originalUrl?: string }) => {
            const [pathname = '/', search = ''] = (ctx.originalUrl || '/').split('?');
            const route = parseAppPath(pathname, '', search);
            const origin = 'https://test.scriptorium.ro';
            const seo = await buildReaderPageSeo({
              route,
              origin,
              path: route.view === 'reader' ? canonicalReaderPath(pathname) : pathname,
              searchParams: new URLSearchParams(search),
              bibliotecaServerUrl: BIBLIOTECA_SERVER_URL,
              defaultImage: defaultOgImage(origin),
            });
            const rendered = renderIndexHtml(html, seo);
            return ['reader', 'quote'].includes(route.view) ? rendered.replace('</head>', textAlternates(canonicalReaderPath(pathname), new URLSearchParams(search)) + '</head>') : rendered;
          },
        },
      }],
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    // index: false - otherwise express.static serves dist/index.html's raw
    // __PLACEHOLDER__ template directly for any path that resolves to it
    // (notably '/'), bypassing renderPageFor's SEO templating entirely.
    app.use('/app', express.static(distPath, { index: false }));
    app.use(express.static(distPath, { index: false }));
    const indexHtml = fs.readFileSync(path.join(distPath, 'index.html'), 'utf-8');
    app.get('*', asyncRoute(async (req: Request, res: Response) => {
      try {
        const html = await renderPageFor(req, indexHtml);
        const queryIndex = req.url.indexOf('?');
        const search = queryIndex >= 0 ? req.url.slice(queryIndex) : '';
        const route = parseAppPath(req.path, '', search);
        res.status(route.view === 'notFound' ? 404 : 200).type('html').send(html);
      } catch (error) {
        console.error('Failed to render reader page:', error);
        res.status(500).type('html').send(renderServerErrorPage(publicBasePath()));
      }
    }));
  }

  app.use((error: unknown, req: Request, res: Response, next: NextFunction) => {
    if (res.headersSent) {
      next(error);
      return;
    }
    console.error('Unhandled reader server error:', error);
    if (req.path === '/api' || req.path.startsWith('/api/')) {
      res.status(500).json({ error: 'internal server error' });
      return;
    }
    res.status(500).type('html').send(renderServerErrorPage(publicBasePath()));
  });

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Bilioteca Reader server listening on http://0.0.0.0:${PORT}`);
    if (READ_ONLY) {
      console.log('Read-only mode (reader.config.json readOnly): all state-changing routes return 403; ' +
        `read traffic proxies to ${BIBLIOTECA_SERVER_URL}`);
    }
  });
}

startServer();
